def add_item(
    source: str,
    source_type: Literal[
        "auto", "doi", "url", "isbn", "bibtex", "csl_json", "file"
    ] = "auto",
    collections: list[str] | str | None = None,
    tags: list[str] | str | None = None,
    attach_mode: str = "auto",
    if_exists: Literal["duplicate", "file", "skip"] = "duplicate",
    create_missing_collections: bool = False,
    title: str | None = None,
    *,
    ctx: Context
) -> str:
    """Detect the shape of ``source`` and dispatch to the matching adder."""
    # Tolerate structured CSL JSON arriving as a real object/array rather
    # than a string — clients do this when the user pastes JSON. An empty
    # container is "nothing supplied", not an empty JSON document.
    if source is not None and not isinstance(source, str):
        if isinstance(source, (list, dict)) and not source:
            source = ""
        else:
            try:
                source = json.dumps(source)
            except (TypeError, ValueError):
                return "Error: source must be a string."

    resolved = (source_type or "auto").strip().lower()
    if resolved in ("", "auto"):
        try:
            resolved = detect_source_type(source)
        except ValueError as e:
            return f"Error: {e}"
        ctx.info(f"Detected source_type='{resolved}'")
    elif resolved not in _ADD_SOURCE_TYPES:
        return (
            f"Error: source_type must be 'auto' or one of "
            f"{_ADD_SOURCE_TYPES}."
        )

    source = source.strip() if isinstance(source, str) else source

    common = {
        "collections": collections,
        "tags": tags,
        "if_exists": if_exists,
        "create_missing_collections": create_missing_collections,
        "ctx": ctx,
    }

    if resolved == "doi":
        return add_by_doi(doi=source, attach_mode=attach_mode, **common)
    if resolved == "url":
        return add_by_url(url=source, attach_mode=attach_mode, **common)
    if resolved == "isbn":
        return add_by_isbn(isbn=source, **common)
    if resolved == "file":
        return add_from_file(file_path=source, title=title, **common)
    # BibTeX / CSL JSON arrive either inline or as a path to a citation file.
    if resolved == "bibtex":
        if _is_citation_path(source, _BIBTEX_EXTS):
            return add_by_bibtex(file_path=source, attach_mode=attach_mode, **common)
        return add_by_bibtex(bibtex=source, attach_mode=attach_mode, **common)
    if _is_citation_path(source, _CSL_JSON_EXTS):
        return add_by_csl_json(file_path=source, attach_mode=attach_mode, **common)
    return add_by_csl_json(csl_json=source, attach_mode=attach_mode, **common)

def analyze_component(
    addrs: Annotated[list[str] | str, "Function addresses (comma-separated or list)"],
) -> AnalyzeComponentResult:
    """Analyze related functions as a group: per-function summaries, internal call graph, shared data."""

    import idaapi
    import idautils

    raw = normalize_list_input(addrs)
    if not raw:
        return {"error": "Empty address list"}

    ea_map: dict[int, str] = {}
    for a in raw:
        try:
            ea_map[_resolve_addr(a)] = a
        except IDAError:
            return {"error": f"Cannot resolve address: {a!r}"}

    ea_set = set(ea_map.keys())

    # --- Per-function COMPACT summary (no decompile, no disasm) ---
    functions: list[dict] = []
    for ea in ea_set:
        func = idaapi.get_func(ea)
        if func is None:
            functions.append({"addr": hex(ea), "error": "No function"})
            continue
        name = idaapi.get_func_name(ea) or ""
        strings_raw = extract_function_strings(ea)
        top_strings = _compact_strings(strings_raw, limit=5)
        callee_list = _compact_callees(get_callees(hex(ea)))
        bb = _basic_block_info(ea)
        functions.append({
            "addr": hex(ea),
            "name": name,
            "prototype": get_prototype(func),
            "size": func.end_ea - func.start_ea,
            "callees": callee_list,
            "strings": top_strings,
            "basic_blocks": bb["count"],
            "complexity": bb["cyclomatic_complexity"],
        })

    # --- Internal call graph ---
    nodes = [hex(ea) for ea in ea_set]
    edges: list[dict] = []
    for ea in ea_set:
        for callee in (get_callees(hex(ea)) or []):
            callee_ea = callee.get("addr")
            if isinstance(callee_ea, str):
                try:
                    callee_ea = int(callee_ea, 16)
                except (ValueError, TypeError):
                    continue
            if callee_ea in ea_set:
                edges.append({
                    "from": hex(ea),
                    "to": hex(callee_ea),
                    "name": callee.get("name", ""),
                })

    # --- Shared globals ---
    func_globals: dict[int, set[int]] = {}
    for ea in ea_set:
        globals_accessed: set[int] = set()
        func = idaapi.get_func(ea)
        if func is None:
            func_globals[ea] = globals_accessed
            continue
        for head in idautils.Heads(func.start_ea, func.end_ea):
            for xref in idautils.XrefsFrom(head, 0):
                if xref.iscode:
                    continue
                ref_func = idaapi.get_func(xref.to)
                if ref_func is None and idaapi.is_loaded(xref.to):
                    globals_accessed.add(xref.to)
        func_globals[ea] = globals_accessed

    global_refcount: dict[int, list[str]] = defaultdict(list)
    for ea, gset in func_globals.items():
        fname = idaapi.get_func_name(ea) or hex(ea)
        for g in gset:
            global_refcount[g].append(fname)

    shared_globals = []
    for g_ea, accessors in sorted(global_refcount.items()):
        if len(accessors) >= 2:
            shared_globals.append({
                "addr": hex(g_ea),
                "name": idaapi.get_name(g_ea) or hex(g_ea),
                "accessed_by": sorted(accessors),
            })

    # --- Interface vs internal ---
    interface_functions: list[str] = []
    internal_only: list[str] = []
    for ea in ea_set:
        callers = get_callers(hex(ea))
        has_external = False
        for c in (callers or []):
            caller_addr = c.get("addr") or c.get("start_ea")
            if isinstance(caller_addr, str):
                try:
                    caller_addr = int(caller_addr, 16)
                except (ValueError, TypeError):
                    has_external = True
                    break
            if caller_addr not in ea_set:
                has_external = True
                break
        if has_external:
            interface_functions.append(hex(ea))
        else:
            internal_only.append(hex(ea))

    # --- String usage across functions ---
    string_funcs: dict[str, set[str]] = defaultdict(set)
    for ea in ea_set:
        fname = idaapi.get_func_name(ea) or hex(ea)
        for s in (extract_function_strings(ea) or []):
            sval = s.get("value") or s.get("string", "")
            if sval:
                string_funcs[sval].add(fname)

    string_usage = {
        s: sorted(fnames)
        for s, fnames in sorted(string_funcs.items())
        if len(fnames) >= 2
    }

    return {
        "functions": functions,
        "internal_call_graph": {"nodes": nodes, "edges": edges},
        "shared_globals": shared_globals,
        "interface_functions": interface_functions,
        "internal_only": internal_only,
        "string_usage": string_usage,
    }

async def unload_tool_group(
    group: Annotated[str, Field(description="Category name to unload")],
    ctx: Context | None = None,
) -> str:
    """
    Unload all tools in a category. Default groups are protected from unloading.

    Args:
        group: Category name to unload
    """
    if group in state._default_groups:
        return json.dumps(
            {
                "error": f"Cannot unload default group '{group}'",
                "default_groups": sorted(state._default_groups),
            }
        )

    state.remember_tools_changed_context(ctx)

    removed = await state.run_in_worker(
        registry._unload_group,
        group,
        done_callback=lambda result: result > 0 and state.notify_tools_changed_from_worker(),
    )
    if removed == 0:
        return json.dumps({"message": f"Group '{group}' is not loaded or has no tools."})
    return json.dumps(
        {
            "unloaded": group,
            "removed_tools": removed,
            "total_loaded": len(state._dynamic_tool_names),
            "loaded_groups": sorted(state._loaded_groups),
        }
    )

